L["Missed an update?"] = "Ein Update verpasst?"
L["Every release's full notes live inside the addon - type %1$s, open the %2$s tab, and read the Changelog there."] = "Die vollständigen Hinweise zu jeder Veröffentlichung sind im Addon enthalten – gebt %1$s ein, öffnet den Tab %2$s und lest dort die Änderungshistorie."
